function atg_tokens(string $text):array{$text=mb_strtolower($text);$text=preg_replace('/[^\p{L}\p{N}\s]+/u',' ',$text)??'';$stop=['what','when','where','which','with','this','that','from','have','does','about','please','tell','your','और','क्या','कैसे','कब','कहाँ','मुझे','है','का','की','के','में','से','को'];$parts=preg_split('/\s+/u',trim($text))?:[];$parts=array_values(array_unique(array_filter($parts,static fn(string $v):bool=>mb_strlen($v)>=3&&!in_array($v,$stop,true))));sort($parts,SORT_STRING);return $parts;}
function atg_key(string $text):string{$t=atg_tokens($text);return $t?implode(' ',array_slice($t,0,3)):'general-question';}
try{$pdo=role_portal_db();role_portal_ensure($pdo);aia_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user){header('Location: ../login.php');exit;}if((string)($user['role_code']??'')!=='admin'){header('Location: access_denied.php');exit;}$orgId=pscms_org_id($pdo);$csrf=security_step17_csrf();
 if($_SERVER['REQUEST_METHOD']==='POST'&&(string)($_POST['action']??'')==='publish'&&str_starts_with(trim((string)($_POST['draft_answer']??'')),'Verified answer required'))throw new RuntimeException('Replace the starter guidance with an accurate verified answer before publishing.');
 if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'create_draft');if($action==='create_draft'){$key=substr(trim((string)($_POST['cluster_key']??'')),0,190);$question=substr(trim((string)($_POST['question_text']??'')),0,1000);$ids=array_values(array_filter(array_map('intval',explode(',',(string)($_POST['source_ids']??'')))));if($key===''||$question==='')throw new RuntimeException('Topic group is incomplete.');$starter="Verified answer required for this repeated visitor topic.\n\nInclude only approved club information, clear eligibility or availability details, and the correct human-support route when confirmation is required.";$s=$pdo->prepare("INSERT INTO public_ai_knowledge_drafts(organization_id,cluster_key,question_text,draft_answer,source_question_ids,created_by,updated_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text),source_question_ids=VALUES(source_question_ids),updated_by=VALUES(updated_by),updated_at=NOW()");$s->execute([$orgId,$key,$question,$starter,json_encode($ids),(int)$user['id'],(int)$user['id']]);$success='Editable knowledge draft created. It is not published yet.';}elseif($action==='save_draft'||$action==='publish'){$id=(int)($_POST['draft_id']??0);$question=substr(trim((string)($_POST['question_text']??'')),0,1000);$answer=trim((string)($_POST['draft_answer']??''));$category=substr(trim((string)($_POST['category']??'General')),0,80)?:'General';if($question===''||mb_strlen($answer)<20)throw new RuntimeException('Complete the question and verified answer before saving.');$s=$pdo->prepare("UPDATE public_ai_knowledge_drafts SET question_text=?,draft_answer=?,category=?,updated_by=?,updated_at=NOW() WHERE id=? AND organization_id=?");$s->execute([$question,$answer,$category,(int)$user['id'],$id,$orgId]);if($action==='publish'){$s=$pdo->prepare("SELECT source_question_ids FROM public_ai_knowledge_drafts WHERE id=? AND organization_id=?");$s->execute([$id,$orgId]);$ids=json_decode((string)$s->fetchColumn(),true);$s=$pdo->prepare("INSERT INTO public_ai_verified_answers(organization_id,source_question_id,question_text,verified_answer,category,status,created_by,updated_by) VALUES(?,NULL,?,?,?,'published',?,?)");$s->execute([$orgId,$question,$answer,$category,(int)$user['id'],(int)$user['id']]);$pdo->prepare("UPDATE public_ai_knowledge_drafts SET status='published' WHERE id=? AND organization_id=?")->execute([$id,$orgId]);if(is_array($ids)&&$ids){$marks=implode(',',array_fill(0,count($ids),'?'));$pdo->prepare("UPDATE public_ai_unanswered SET status='resolved',resolution_note='Resolved through a published topic-gap answer.',resolved_by=?,resolved_at=NOW() WHERE organization_id=? AND id IN($marks)")->execute([(int)$user['id'],$orgId,...array_map('intval',$ids)]);}security_step17_audit($pdo,(int)$user['id'],'ai_topic_draft_published','public_ai_knowledge_draft',$id,['category'=>$category]);$success='Verified topic answer published and related questions resolved.';}else $success='Draft saved for review.';}}
 $s=$pdo->prepare("SELECT id,question_text,page_path,created_at FROM public_ai_unanswered WHERE organization_id=? AND status IN('open','reviewing') ORDER BY created_at DESC LIMIT 250");$s->execute([$orgId]);foreach($s->fetchAll() as $r){$key=atg_key((string)$r['question_text']);if(!isset($clusters[$key]))$clusters[$key]=['key'=>$key,'question'=>(string)$r['question_text'],'ids'=>[],'examples'=>[],'latest'=>(string)$r['created_at']];$clusters[$key]['ids'][]=(int)$r['id'];if(count($clusters[$key]['examples'])<3)$clusters[$key]['examples'][]=(string)$r['question_text'];}uasort($clusters,static fn(array $a,array $b):int=>count($b['ids'])<=>count($a['ids']));$s=$pdo->prepare("SELECT * FROM public_ai_knowledge_drafts WHERE organization_id=? AND status='draft' ORDER BY updated_at DESC");$s->execute([$orgId]);$drafts=$s->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();}
