stion_text'])?>" required></label><label>Category<input name="category" maxlength="80" value="<?=atgh((string)$d['category'])?>"></label><label>Verified answer<textarea name="draft_answer" maxlength="8000" required><?=atgh((string)$d['draft_answer'])?></textarea></label><div class="tg-actions"><button name="action" value="save_draft">Save Draft</button><button name="action" value="publish">Publish Verified Answer</button></div></form><?php endforeach;?></article></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
